const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const css = fs.readFileSync('styles.css', 'utf8');
const js = fs.readFileSync('app.js', 'utf8');
const fail = (m) => { console.error('FAIL', m); process.exit(1); };
if (!/<button[^>]*(id|data-[a-z-]*)="[^"]*(theme|dark|mode)[^"]*"/i.test(html) && !/(theme|dark)/i.test((html.match(/<button[\s\S]*?<\/button>/gi) || []).join(''))) fail('no toggle button');
if (!/prefers-color-scheme\s*:\s*dark/.test(css + js)) fail('OS preference not respected');
if (!/localStorage/.test(js)) fail('choice not persisted');
if (!/(\.dark|\[data-theme|data-color-scheme|color-scheme)/.test(css)) fail('no dark styles');
console.log('hidden ok');
